function read(key){try{return JSON.parse(localStorage.getItem(key));}catch{return null;}}
function save(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true;}catch{return false;}}
let language=read('saia-language')==='en'?'en':'pt',current=null,worker=null,pending=null,timeout=null,timerInterval=null,endAt=0,activePause=null,reflectionActivity=null,cardUrl=null;
const t=key=>copy[language][key]??key;
function example(){return createPlan({duration:20,goal:'quiet',place:t('placeDefault'),context:'',seated:true},'A','catalog');}
function renderPlan(){
 const preview=!current,plan=current??example(),text=planText(plan,language);
 $('#plan').innerHTML=`<article class="plan-card"><div class="plan-card-head"><div><span class="plan-tag">${t('smallPlan')}</span><h3>${h(text.title)}</h3><p>${h(plan.preferences.place)}</p></div><span class="plan-time">${plan.preferences.duration}<small>min</small></span></div><div class="plan-steps">${text.steps.map(s=>`<div class="plan-step"><span class="minute">${s.minutes} min</span><div><h4>${h(s.title)}</h4><p>${h(s.body)}</p></div></div>`).join('')}</div><p class="plan-note">${t('rhythm')}</p></article>${preview?`<p class="preview-note">${t('example')}</p>`:''}`;
 $('#plan-state').textContent=preview?t('preview'):plan.source==='local-ai'?t('ai'):t('catalog');
 if(!preview){if(cardUrl)URL.revokeObjectURL(cardUrl);cardUrl=URL.createObjectURL(new Blob([pocketCard(plan,language)],{type:'text/html'}));$('#download').href=cardUrl;}
 $('#plan-actions').hidden=preview;$('#evidence').hidden=preview||plan.source!=='local-ai';
 if(!preview&&plan.source==='local-ai')$('#evidence').innerHTML=`<details><summary>${t('proof')}</summary><p>${t('local')}</p><pre>${h((plan.evidence.ranking??[]).map(item=>`${item.id} · ${item.score}`).join('\n'))}</pre></details>`;
}
function setStartLabel(){$('#start').textContent=t(activePause?'resume':'start');}
function translate(){document.documentElement.lang=language==='pt'?'pt-BR':'en';document.title=language==='pt'?'Saia em 20 — uma pausa lá fora':'Saia em 20 — Outside in 20';for(const el of document.querySelectorAll('[data-i18n]'))el.innerHTML=t(el.dataset.i18n);$('#language').textContent=language==='pt'?'EN':'PT';$('#language').setAttribute('aria-label',language==='pt'?'Switch to English':'Mudar para português');$('#context').placeholder=t('contextPlaceholder');renderPlan();setStartLabel();}
function preferences(){const f=new FormData($('#plan-form'));return validatePreferences({duration:f.get('duration'),goal:f.get('goal'),place:f.get('place'),context:f.get('context')??'',seated:$('#seated').checked});}
function busy(value){$('#generate').disabled=value;$('#cancel').hidden=!value;$('#download-progress').hidden=!value;$('#model-status').hidden=false;}
function closeWorker(){worker?.terminate();worker=null;clearTimeout(timeout);timeout=null;}
async function prepare(input){
 if(pending)throw new Error('A plan is already being prepared');
 const p=validatePreferences(input),candidates=candidatesFor(p);
 busy(true);$('#error').hidden=true;$('#model-status').textContent=t('loading');$('#download-progress').value=0;
 const preference=p.context || (p.goal==='quiet'?'Rest quietly outside and slow down':p.goal==='notice'?'Observe small natural details outside':'A gentle self-paced walk in a familiar outdoor place');
 worker??=new Worker(new URL('./ai-worker.js',import.meta.url),{type:'module'});
 const result=new Promise((resolve,reject)=>{pending={resolve,reject,p};});
 worker.onmessage=({data})=>{
  if(data.type==='progress'&&data.event.status==='progress'){$('#download-progress').value=Math.min(100,data.event.progress??0);$('#model-status').textContent=`${t('downloading')}… ${Math.round((data.event.loaded??0)/1e6)} MB`;}
  else if(data.type==='ready'){$('#model-status').textContent=t('thinking');$('#download-progress').value=100;}
  else if(data.type==='result'){
   try{current=createPlan(pending.p,data.id,'local-ai',data.evidence);save('saia-plan',current);renderPlan();$('#model-status').textContent=t('ready');pending.resolve({id:current.activityId,source:current.source,model:MODEL});}
   catch(error){pending.reject(error);}
   finally{pending=null;clearTimeout(timeout);busy(false);}
  }else if(data.type==='error')fail(new Error(data.message));
 };
 worker.onerror=()=>fail(new Error('AI worker failed'));
 timeout=setTimeout(()=>fail(new Error('AI preparation timed out')),300000);
 worker.postMessage({type:'generate',candidates:candidates.map(({id,descriptionEn})=>({id,descriptionEn})),preference});
 return result;
}
function fail(error){const job=pending;pending=null;closeWorker();busy(false);$('#model-status').hidden=true;$('#error').hidden=false;$('#error').replaceChildren();const text=document.createElement('p');text.textContent=t('error');const fallback=document.createElement('button');fallback.className='secondary';fallback.textContent=t('fallback');fallback.onclick=()=>{const p=job?.p??preferences();current=createPlan(p,candidatesFor(p)[0].id,'catalog');save('saia-plan',current);renderPlan();$('#error').hidden=true;};$('#error').append(text,fallback);job?.reject(error);}
$('#plan-form').addEventListener('submit',async event=>{event.preventDefault();try{await prepare(preferences());}catch(error){console.warn('Plan generation:',error.message);}});
$('#cancel').onclick=()=>{const job=pending;pending=null;closeWorker();busy(false);$('#model-status').textContent=t('cancelled');job?.reject(new Error('Cancelled'));};
$('#language').onclick=()=>{const old=t('placeDefault');language=language==='pt'?'en':'pt';save('saia-language',language);if($('#place').value===old)$('#place').value=t('placeDefault');translate();};
function updateTimer(){const seconds=remainingSeconds(endAt);$('#timer').textContent=`${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`;if(!seconds)clearInterval(timerInterval);}
function showPause(){if(!current&&!activePause)return;activePause??={endAt:Date.now()+current.preferences.duration*60000,plan:current};endAt=activePause.endAt;const persisted=save('saia-pause',activePause);$('#pause-dialog [data-i18n=timerHint]').textContent=t(persisted?'timerHint':'timerUnsaved');$('#pause-place').textContent=activePause.plan.preferences.place;$('#pause-instruction').textContent=planText(activePause.plan,language).steps[1].body;$('#pause-dialog').showModal();clearInterval(timerInterval);updateTimer();timerInterval=setInterval(updateTimer,1000);setStartLabel();}
$('#start').onclick=showPause;
$('#close-pause').onclick=()=>$('#pause-dialog').close();
$('#finish').onclick=()=>{reflectionActivity=activePause?.plan.activityId;activePause=null;save('saia-pause',null);setStartLabel();$('#pause-dialog').close();clearInterval(timerInterval);$('#reflection').hidden=false;$('#reflection').scrollIntoView({behavior:'smooth'});$('#reflection [data-reflect]').focus();};
for(const button of document.querySelectorAll('[data-reflect]'))button.onclick=()=>{const outcome=button.dataset.reflect;let persisted=true;if(outcome!=='skip'){const storedHistory=read('saia-reflections');const history=Array.isArray(storedHistory)?storedHistory:[];persisted=save('saia-reflections',[...history,{at:new Date().toISOString(),activityId:reflectionActivity??current?.activityId,outcome}].slice(-30));}$('#reflection-result').textContent=t(outcome==='skip'?'skipped':persisted?'saved':'notSaved');};

const stored=read('saia-plan');try{if(stored&&stored.version===1)current={...createPlan(stored.preferences,stored.activityId,stored.source,stored.evidence),createdAt:stored.createdAt};}catch{}
const storedPause=read('saia-pause');try{if(storedPause&&Number.isFinite(storedPause.endAt)&&storedPause.endAt>0&&storedPause.endAt<=Date.now()+30*60000){const p=storedPause.plan;activePause={endAt:storedPause.endAt,plan:{...createPlan(p.preferences,p.activityId,p.source,p.evidence),createdAt:p.createdAt}};}}catch{}
translate();
if(current){const p=current.preferences;$('#place').value=p.place;$('#context').value=p.context;$('#seated').checked=p.seated;$(`input[name=duration][value="${p.duration}"]`).checked=true;$(`input[name=goal][value="${p.goal}"]`).checked=true;}
if(activePause)showPause();
if('serviceWorker' in navigator)navigator.serviceWorker.register(new URL('./sw.js',import.meta.url)).catch(()=>{});
const context=document.modelContext;
if(context?.registerTool){
 const lifecycle=new AbortController();
 const tools=[{name:'read_outdoor_plan',title:'Read outdoor plan',description:'Read the current saved outdoor plan; does not generate or start a timer.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>current?{activityId:current.activityId,source:current.source,duration:current.preferences.duration,place:current.preferences.place}:null},{name:'prepare_outdoor_plan',title:'Prepare outdoor plan',description:'Generate with the local open model and save on this device. Does not start the break.',inputSchema:{type:'object',properties:{duration:{type:'integer',enum:[10,20,30]},goal:{type:'string',enum:['quiet','notice','move']},place:{type:'string',minLength:1,maxLength:80},context:{type:'string',maxLength:180},seated:{type:'boolean'}},required:['duration','goal','place','context','seated'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute:async input=>{const p=validatePreferences(input);$('#place').value=p.place;$('#context').value=p.context;$('#seated').checked=p.seated;$(`input[name=duration][value="${p.duration}"]`).checked=true;$(`input[name=goal][value="${p.goal}"]`).checked=true;return prepare(p);}}];
 for(const tool of tools)try{Promise.resolve(context.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}
 addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
}
